// @vitest-environment jsdom
import fs from'node:fs';import{stripTypeScriptTypes}from'node:module';import path from'node:path';import {describe,it,expect,vi,beforeEach}from'vitest';import{QueryClient,MutationCache}from'@tanstack/react-query';import{ApiSessionChangedError,beginApiSessionChange}from'@/api/client';import{CommentSubmissionUnknownError}from'@/lib/comment-submit-result';import{saveDraft,loadDraft,saveDraftSubmission,loadDraftSubmission}from'@/lib/composer-draft';
const main=fs.readFileSync(path.resolve(process.cwd(),'ui/src/main.tsx'),'utf8');const create=main.slice(main.indexOf('function createAccountClient('),main.indexOf('function AccountQueryProvider('));
// Evaluate the actual production factory, preserving QueryCore behavior and callback order.
const js=stripTypeScriptTypes(create,{mode:'transform'});const factory=Function('QueryClient','MutationCache','ApiSessionChangedError',`${js};return createAccountClient;`)(QueryClient,MutationCache,ApiSessionChangedError)as(previous?:QueryClient)=>{client:QueryClient;retire:()=>void};
function deferred<T>(){let resolve!:(v:T)=>void;let reject!:(e:unknown)=>void;const promise=new Promise<T>((r,j)=>{resolve=r;reject=j;});return{resolve,reject,promise};}
beforeEach(()=>{localStorage.clear();sessionStorage.clear();});
describe('production QueryClient owner leases',()=>{
 it.each(['personal-connection','secret','attachment','task'])('keeps late %s success callbacks off the new owner client',async kind=>{const a=factory();const result=deferred<unknown>();const hook=vi.fn(()=>a.client.setQueryData([kind],{owner:'A'}));const settled=vi.fn();const mutation=a.client.getMutationCache().build(a.client,{mutationFn:()=>result.promise,onSuccess:hook,onSettled:settled});const pending=mutation.execute(undefined).catch(e=>e);await new Promise(resolve=>setTimeout(resolve,0));a.client.setQueryData(['health'],{deploymentMode:'authenticated'});a.client.setQueryData(['private-a'],{owner:'A'});a.retire();const b=factory(a.client);b.client.setQueryData([kind],{owner:'B'});result.resolve({committed:true});expect(await pending).toBeInstanceOf(ApiSessionChangedError);expect(hook).not.toHaveBeenCalled();expect(settled).not.toHaveBeenCalled();expect(b.client.getQueryData([kind])).toEqual({owner:'B'});expect(b.client.getQueryData(['private-a'])).toBeUndefined();expect(b.client.getQueryData(['health'])).toEqual({deploymentMode:'authenticated'});});
 it('blocks late old-owner error rollbacks and settled callbacks too',async()=>{const a=factory();const result=deferred<unknown>();const rollback=vi.fn(()=>a.client.setQueryData(['issue'],{owner:'A'}));const settled=vi.fn();const mutation=a.client.getMutationCache().build(a.client,{mutationFn:()=>result.promise,onError:rollback,onSettled:settled});const pending=mutation.execute(undefined).catch(e=>e);await new Promise(resolve=>setTimeout(resolve,0));a.retire();const b=factory(a.client);b.client.setQueryData(['issue'],{owner:'B'});result.reject(new Error('late old error'));expect(await pending).toBeInstanceOf(ApiSessionChangedError);expect(rollback).not.toHaveBeenCalled();expect(settled).not.toHaveBeenCalled();expect(b.client.getQueryData(['issue'])).toEqual({owner:'B'});});
 it('retains A unknown submission fence after commit with a late response and never replays the write',async()=>{const a=factory();const result=deferred<unknown>();const write=vi.fn(()=>result.promise);const keyA='paperclip:issue-comment-draft:company:A:task',keyB='paperclip:issue-comment-draft:company:B:task';saveDraft(keyA,'A private queued text');saveDraftSubmission(keyA,{attemptId:'9af8228f-0be7-45ae-a104-6fbe0af6f1d3',reviewed:false});const mutation=a.client.getMutationCache().build(a.client,{mutationFn:write});const pending=mutation.execute(undefined).catch(e=>e);await new Promise(resolve=>setTimeout(resolve,0));a.retire();factory(a.client);result.resolve({committed:true});const error=await pending;expect(error).toBeInstanceOf(CommentSubmissionUnknownError);expect(loadDraft(keyB)).toBe('');expect(loadDraftSubmission(keyB)).toBeNull();expect(loadDraft(keyA)).toBe('A private queued text');expect(loadDraftSubmission(keyA)?.reviewed).toBe(false);expect(write).toHaveBeenCalledTimes(1);});
 it('prevents an old-owner write dispatch that was still waiting inside onMutate',async()=>{const a=factory();const gate=deferred<unknown>();const write=vi.fn(async()=>({written:true}));const mutation=a.client.getMutationCache().build(a.client,{onMutate:()=>gate.promise,mutationFn:write});const pending=mutation.execute(undefined).catch(e=>e);await new Promise(resolve=>setTimeout(resolve,0));a.retire();factory(a.client);gate.resolve(null);expect(await pending).toBeInstanceOf(ApiSessionChangedError);expect(write).not.toHaveBeenCalled();});
 it('does not retire an active sender auth lease merely because its same-tab HTTP epoch rotated',async()=>{const a=factory();const result=deferred<unknown>();const success=vi.fn();const mutation=a.client.getMutationCache().build(a.client,{mutationFn:()=>result.promise,onSuccess:success});const pending=mutation.execute(undefined);const finish=beginApiSessionChange(true);finish();result.resolve({signedIn:true});await pending;expect(success).toHaveBeenCalledOnce();});
 it('cannot restore retired callbacks by updating an old observer before React unmounts it',async()=>{const a=factory();const response=deferred<unknown>();const success=vi.fn();const mutation=a.client.getMutationCache().build(a.client,{mutationFn:()=>response.promise});const pending=mutation.execute(undefined).catch(e=>e);await new Promise(resolve=>setTimeout(resolve,0));a.retire();mutation.setOptions({mutationFn:()=>response.promise,onSuccess:success,onError:success,onSettled:success});response.resolve({committed:true});expect(await pending).toBeInstanceOf(ApiSessionChangedError);expect(success).not.toHaveBeenCalled();});

});
